var ITEMS=[["What welders do","Welders join metal with heat: structural steel, pipelines, pressure vessels, automotive, and artistic fabrication. The main processes are MIG, TIG, stick, and flux-core \u2014 each with its sweet spot. Certified welders in pi"], ["Essential tools","Welding machine, auto-darkening helmet, MIG gun or TIG torch, stick electrode holder, angle grinder with cutting and grinding discs, chipping hammer, wire brush, clamps, magnets, soapstone markers, and proper PPE."], ["Key skills","Steady travel speed, correct arc length, reading weld symbols on blueprints, joint preparation (beveling, cleaning), and knowing which process and settings fit each metal and position. Overhead and vertical positions sep"], ["Safety essentials","Arc flash burns eyes in seconds \u2014 helmet always down. Ventilate: welding fumes are toxic, especially galvanized steel (metal fume fever). Fire watch: sparks travel; keep extinguishers close. Leather, not synthetics \u2014 syn"], ["Getting started","Trade school or community college welding programs teach the basics in months. Practice every position, then test for AWS certifications (3G/4G plate, 6G pipe). Pipeline and underwater welding are the elite paths."], ["Pro tips","Clean metal welds better than any settings trick \u2014 grind to bright metal. Tack everything before full welds. Watch the puddle, not the arc. Keep a weld log of settings that worked. Grind your restarts."], ["MIG (GMAW)","Trade term \u2014 MIG (GMAW): Wire-feed welding with shielding gas; fastest to learn."], ["TIG (GTAW)","Trade term \u2014 TIG (GTAW): Tungsten inert gas; precise, beautiful, slow."], ["Stick (SMAW)","Trade term \u2014 Stick (SMAW): Shielded metal arc; rugged, outdoor-friendly."], ["Flux-core (FCAW)","Trade term \u2014 Flux-core (FCAW): Wire welding with flux; windy-day MIG alternative."], ["Arc length","Trade term \u2014 Arc length: The gap between electrode and work; controls heat and spatter."], ["Travel speed","Trade term \u2014 Travel speed: How fast the weld progresses; too fast or slow both fail."], ["Penetration","Trade term \u2014 Penetration: How deep the weld fuses into the base metal."], ["Undercut","Trade term \u2014 Undercut: A groove melted into the base metal beside the weld; a defect."], ["Porosity","Trade term \u2014 Porosity: Gas bubbles trapped in the weld; caused by contamination."], ["Slag","Trade term \u2014 Slag: The flux coating residue on stick welds; must be chipped."], ["Tack weld","Trade term \u2014 Tack weld: Small temporary welds holding parts for final welding."], ["Bevel","Trade term \u2014 Bevel: The angled edge prep for full-penetration joints."], ["Weld symbol","Trade term \u2014 Weld symbol: Blueprint notation specifying weld type and size."], ["6G position","Trade term \u2014 6G position: The pipe welding test position: 45 degrees fixed; the gold standard cert."], ["Duty cycle","Trade term \u2014 Duty cycle: How many minutes per 10 a welder can run at a given amperage."], ["Polarity","Trade term \u2014 Polarity: DCEN vs DCEP: which way current flows changes penetration."], ["Shielding gas","Trade term \u2014 Shielding gas: Gas protecting the molten weld from air; usually argon mixes."], ["Fume fever","Trade term \u2014 Fume fever: Flu-like illness from welding galvanized steel without ventilation."], ["Hot pass","Trade term \u2014 Hot pass: The weld pass after the root, building the joint."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
